    const fromIndex = STAGES.findIndex((item) => item.key === fromStage)
    const next = STAGES[fromIndex + 1]
    if (!next) return null
    const unlocked = fromIndex + 1 <= currentStageIndex
    const reason = stageBlockedExplanation(fromStage)
    const button = (
